import {useCallback, useEffect, useMemo, useState} from 'react'
import {Link, useSearchParams} from '@github-ui/react-router'
import {verifiedFetch, verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {Icon} from '@primer/octicons-react'
import {
  CacheIcon,
  MeterIcon,
  PinIcon,
  PinSlashIcon,
  RocketIcon,
  ServerIcon,
  VerifiedIcon,
  ArrowUpRightIcon,
  SearchIcon,
  SortDescIcon,
  XIcon,
} from '@primer/octicons-react'
import {ActionMenu, ActionList, IconButton, NavList, Tooltip} from '@primer/react'
import type {Workflow} from '../views/models'
import type {WorkflowsLayoutPayload} from '../routes/workflows-layout-route'
import {workflowsLayoutRoute} from '../routes/workflows-layout-route'
import styles from './WorkflowSidebar.module.css'

interface ManagementItem {
  label: string
  href: string
  icon: Icon
  external?: boolean
}

interface WorkflowSidebarProps {
  workflows: Workflow[]
  totalCount: number
  pinnedWorkflowIds: number[]
  allowPinning: boolean
  owner: string
  repo: string
  selectedWorkflowFile?: string
  showDeployments: boolean
  showAttestations: boolean
  showRunners: boolean
  showUsageMetrics: boolean
  refreshWorkflows: () => void
}

export function WorkflowSidebar({
  workflows: initialWorkflows,
  totalCount,
  pinnedWorkflowIds: initialPinnedIds,
  allowPinning,
  owner,
  repo,
  selectedWorkflowFile,
  showDeployments,
  showAttestations,
  showRunners,
  showUsageMetrics,
  refreshWorkflows,
}: WorkflowSidebarProps) {
  const [searchParams] = useSearchParams()
  const search = searchParams.toString()
  const qs = search ? `?${search}` : ''
  const allWorkflowsHref = `/${owner}/${repo}/actions${qs}`

  const [extraWorkflows, setExtraWorkflows] = useState<Workflow[]>([])
  const [nextPage, setNextPage] = useState(2)
  const [loading, setLoading] = useState(false)

  // Reset pagination when initial data changes (e.g. route navigation)
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setExtraWorkflows([])
    setNextPage(2)
  }, [initialWorkflows])

  const workflows = useMemo(() => [...initialWorkflows, ...extraWorkflows], [initialWorkflows, extraWorkflows])
  const hasMore = workflows.length < totalCount

  const pinnedIds = useMemo(() => new Set(initialPinnedIds), [initialPinnedIds])

  const [searchFilter, setSearchFilter] = useState('')
  const [sortMode, setSortMode] = useState<'alphabetical' | 'last-run'>('last-run')

  const filteredWorkflows = useMemo(() => {
    if (!searchFilter) return workflows
    const lower = searchFilter.toLowerCase()
    return workflows.filter(w => w.name.toLowerCase().includes(lower))
  }, [workflows, searchFilter])

  const sortedWorkflows = useMemo(() => {
    if (sortMode === 'alphabetical') {
      return [...filteredWorkflows].sort((a, b) => a.name.localeCompare(b.name))
    }
    // 'last-run' keeps server order (most recent first)
    return filteredWorkflows
  }, [filteredWorkflows, sortMode])

  const pinned = useMemo(() => sortedWorkflows.filter(w => pinnedIds.has(w.id)), [sortedWorkflows, pinnedIds])
  const unpinned = useMemo(() => sortedWorkflows.filter(w => !pinnedIds.has(w.id)), [sortedWorkflows, pinnedIds])

  const handlePin = useCallback(
    async (workflowId: number) => {
      try {
        const formData = new FormData()
        formData.append('workflow_id', String(workflowId))
        const resp = await verifiedFetch(`/${owner}/${repo}/actions/pinned_workflows`, {
          method: 'POST',
          body: formData,
          headers: {Accept: 'application/json'},
        })
        // Always refetch to sync sidebar state with server
        refreshWorkflows()
        if (!resp.ok) {
          try {
            const data = (await resp.json()) as {error?: string}
            if (data?.error) {
              // eslint-disable-next-line no-console
              console.warn(`Pin failed: ${data.error}`)
            }
          } catch {
            // response may not be JSON
            // eslint-disable-next-line no-console
            console.warn(`Unpin failed: ${resp.status} ${resp.statusText}`)
          }
        }
      } catch {
        refreshWorkflows()
      }
    },
    [owner, repo, refreshWorkflows],
  )

  const handleUnpin = useCallback(
    async (workflowId: number) => {
      try {
        const resp = await verifiedFetch(`/${owner}/${repo}/actions/pinned_workflows/${workflowId}`, {
          method: 'DELETE',
          headers: {Accept: 'application/json'},
        })
        // Always refetch to sync sidebar state with server
        refreshWorkflows()
        if (!resp.ok) {
          try {
            const data = (await resp.json()) as {error?: string}
            if (data?.error) {
              // eslint-disable-next-line no-console
              console.warn(`Unpin failed: ${data.error}`)
            }
          } catch {
            // response may not be JSON
            // eslint-disable-next-line no-console
            console.warn(`Unpin failed: ${resp.status} ${resp.statusText}`)
          }
        }
      } catch {
        refreshWorkflows()
      }
    },
    [owner, repo, refreshWorkflows],
  )

  const loadMore = useCallback(async () => {
    if (loading) return
    setLoading(true)
    try {
      const resp = await verifiedFetchJSON(`/${owner}/${repo}/actions/_layout?page=${nextPage}`)
      if (resp.ok) {
        const data = (await resp.json()) as {payload: Record<string, WorkflowsLayoutPayload>}
        const pageData = data.payload[workflowsLayoutRoute.id]
        if (pageData) {
          setExtraWorkflows(prev => [...prev, ...pageData.workflows])
          setNextPage(prev => prev + 1)
        }
      }
    } finally {
      setLoading(false)
    }
  }, [owner, repo, nextPage, loading])

  const managementItems = useMemo<ManagementItem[]>(() => {
    const items: ManagementItem[] = [{label: 'Caches', href: `/${owner}/${repo}/actions/caches`, icon: CacheIcon}]
    if (showDeployments) {
      items.push({label: 'Deployments', href: `/${owner}/${repo}/deployments`, icon: RocketIcon, external: true})
    }
    if (showAttestations) {
      items.push({label: 'Attestations', href: `/${owner}/${repo}/attestations`, icon: VerifiedIcon, external: true})
    }
    if (showRunners) {
      items.push({label: 'Runners', href: `/${owner}/${repo}/settings/actions/runners`, icon: ServerIcon})
    }
    if (showUsageMetrics) {
      items.push(
        {label: 'Usage metrics', href: `/${owner}/${repo}/actions/usage`, icon: MeterIcon, external: true},
        {label: 'Performance metrics', href: `/${owner}/${repo}/actions/performance`, icon: MeterIcon, external: true},
      )
    }
    return items
  }, [owner, repo, showDeployments, showAttestations, showRunners, showUsageMetrics])

  return (
    <>
      <div className={styles.filterBar}>
        <div className={styles.filterInputWrapper}>
          <SearchIcon size={16} className={styles.filterIcon} />
          <input
            type="text"
            placeholder="Filter workflows..."
            aria-label="Filter workflows"
            value={searchFilter}
            onChange={e => setSearchFilter(e.target.value)}
            className={styles.filterInput}
          />
          {searchFilter && (
            <button
              type="button"
              onClick={() => setSearchFilter('')}
              className={styles.filterClear}
              aria-label="Clear filter"
            >
              <XIcon size={14} />
            </button>
          )}
        </div>
        <ActionMenu>
          <ActionMenu.Anchor>
            <IconButton
              icon={SortDescIcon}
              aria-label="Sort workflows"
              variant="invisible"
              className={styles.sortButton}
            />
          </ActionMenu.Anchor>
          <ActionMenu.Overlay>
            <ActionList selectionVariant="single">
              <ActionList.Item selected={sortMode === 'alphabetical'} onSelect={() => setSortMode('alphabetical')}>
                A–Z
              </ActionList.Item>
              <ActionList.Item selected={sortMode === 'last-run'} onSelect={() => setSortMode('last-run')}>
                Last run
              </ActionList.Item>
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </div>

      <NavList aria-label="Actions workflows">
        <NavList.Item as={Link} to={allWorkflowsHref} aria-current={!selectedWorkflowFile ? 'page' : undefined}>
          All workflows
        </NavList.Item>

        {sortedWorkflows.length > 0 ? (
          <NavList.Group>
            {pinned.map(workflow => (
              <WorkflowNavItem
                key={workflow.id}
                workflow={workflow}
                owner={owner}
                repo={repo}
                queryString={qs}
                isSelected={selectedWorkflowFile === workflowFilename(workflow.path)}
                isPinned
                allowPinning={allowPinning}
                onPin={handlePin}
                onUnpin={handleUnpin}
              />
            ))}
            {unpinned.map(workflow => (
              <WorkflowNavItem
                key={workflow.id}
                workflow={workflow}
                owner={owner}
                repo={repo}
                queryString={qs}
                isSelected={selectedWorkflowFile === workflowFilename(workflow.path)}
                isPinned={false}
                allowPinning={allowPinning}
                onPin={handlePin}
                onUnpin={handleUnpin}
              />
            ))}
            {hasMore && (
              <NavList.Item onClick={loadMore} style={{cursor: loading ? 'wait' : 'pointer'}}>
                <span style={{color: 'var(--fgColor-accent)'}}>{loading ? 'Loading…' : 'Show more workflows…'}</span>
              </NavList.Item>
            )}
          </NavList.Group>
        ) : (
          <NavList.Item aria-disabled="true" style={{color: 'var(--fgColor-muted)', fontSize: 14, cursor: 'default'}}>
            {searchFilter ? 'No matching workflows' : 'No workflows found'}
          </NavList.Item>
        )}

        <NavList.Group title="Management">
          {managementItems.map(item => (
            <NavList.Item key={item.label} href={item.href}>
              <NavList.LeadingVisual>
                <item.icon />
              </NavList.LeadingVisual>
              {item.label}
              {item.external && (
                <NavList.TrailingVisual>
                  <ArrowUpRightIcon />
                </NavList.TrailingVisual>
              )}
            </NavList.Item>
          ))}
        </NavList.Group>
      </NavList>
    </>
  )
}

interface WorkflowNavItemProps {
  workflow: Workflow
  owner: string
  repo: string
  queryString: string
  isSelected: boolean
  isPinned: boolean
  allowPinning: boolean
  onPin: (workflowId: number) => void
  onUnpin: (workflowId: number) => void
}

function workflowFilename(path: string): string {
  return path.split('/').pop() ?? path
}

function WorkflowNavItem({
  workflow,
  owner,
  repo,
  queryString,
  isSelected,
  isPinned,
  allowPinning,
  onPin,
  onUnpin,
}: WorkflowNavItemProps) {
  const href = `/${owner}/${repo}/actions/workflows/${workflowFilename(workflow.path)}${queryString}`

  return (
    <Tooltip text={workflow.name} direction="s">
      <NavList.Item
        as={Link}
        to={href}
        aria-current={isSelected ? 'page' : undefined}
        className={styles.navItem}
        style={{overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap'}}
      >
        {workflow.name}
        {allowPinning && (
          <NavList.TrailingAction
            as="button"
            icon={isPinned ? PinSlashIcon : PinIcon}
            label={isPinned ? `Unpin ${workflow.name}` : `Pin ${workflow.name}`}
            className={isPinned ? styles.pinnedIcon : styles.pinButton}
            onClick={() => {
              if (isPinned) {
                onUnpin(workflow.id)
              } else {
                onPin(workflow.id)
              }
            }}
          />
        )}
      </NavList.Item>
    </Tooltip>
  )
}
