import {Flash, Link} from '@primer/react'

interface ReactToggleBannerProps {
  reactToggle: string
}

export function ReactToggleBanner({reactToggle}: ReactToggleBannerProps) {
  return (
    <Flash
      variant="warning"
      style={{marginBottom: 16, display: 'flex', alignItems: 'center', justifyContent: 'space-between'}}
    >
      <span>You are viewing the React UI.</span>
      <Link href={reactToggle}>Switch to classic</Link>
    </Flash>
  )
}
