import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useParams} from '@github-ui/react-router'
import {workflowRunsRoute} from './workflow-runs-route'
import {WorkflowRunsTable} from '../components/WorkflowRunsTable'
import {ReactToggleBanner} from '../components/ReactToggleBanner'

export function WorkflowRuns() {
  const payload = useRouteQuery(workflowRunsRoute, 'mainQuery')
  const {filename} = useParams()

  return (
    <>
      <ReactToggleBanner reactToggle={payload.data.reactToggle} />
      <WorkflowRunsTable title={`Workflow Runs - ${filename}`} workflowRuns={payload.data.workflowRuns} />
    </>
  )
}
